'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
const html = fs.readFileSync(path.join(root, 'index.html'), 'utf8');
const main = fs.readFileSync(path.join(root, 'main.cjs'), 'utf8');
const mediaExport = fs.readFileSync(path.join(root, 'media-export.cjs'), 'utf8');
const workflow = fs.readFileSync(path.join(root, '..', '.github', 'workflows', 'release.yml'), 'utf8');
assert.equal(pkg.version, '2.4.34');
assert.match(pkg.build.win.extraResources.map(x => `${x.from}=>${x.to}`).join('\n'), /vendor\/win=>downloader/);
assert.match(pkg.build.linux.extraResources.map(x => `${x.from}=>${x.to}`).join('\n'), /vendor\/linux=>downloader/);
assert.match(main, /function bundledToolPath\(/);
assert.match(fs.readFileSync(path.join(root, 'media-tools.cjs'), 'utf8'), /pathApi\.join\(resourcesPath, 'downloader', filename\)/);
assert.match(main, /resourcesPath: process\.resourcesPath/);
assert.match(main, /function configureBundledMediaTools\(/);
assert.match(main, /configureBundledMediaTools\(\);/);
assert.match(main, /process\.env\.FRAME_FFMPEG_PATH = ffmpeg/);
assert.match(main, /process\.env\.FRAME_FFPROBE_PATH = ffprobe/);
assert.match(mediaExport, /resolveToolPath\('ffmpeg'/);
assert.match(mediaExport, /resolveToolPath\('ffprobe'/);
assert.match(workflow, /Verify bundled tools are inside the Windows app resources/);
assert.match(workflow, /Verify bundled tools are inside the Linux app resources/);
assert.match(workflow, /vendor\\win/);
assert.match(workflow, /vendor\/linux/);
assert.match(html, /id="timelineundo" data-command="undo"|data-command="undo" id="timelineundo"/);
assert.match(html, /id="timelineredo" data-command="redo"|data-command="redo" id="timelineredo"/);
assert.match(html, /function refreshShortcutTooltips\(/);
assert.match(html, /Shortcut: \$\{hint\}/);
assert.match(html, /function attachPreviewTextEditing\(/);
assert.match(html, /current\?\.kind==='text'&&visible\.some\(c=>c\.id===current\.id\)/);
assert.match(html, /ranked\.length===1\|\|ranked\[0\]\?\.score<=9/);
console.log('FRAME Studio 2.4.23 bundled tools, text editing and shortcut tooltips checks: OK');
